css:
.giantsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2a2118;
    background: linear-gradient(160deg, #f6efe2 0%, #efe3cf 100%);
    border-radius: 18px;
}

.giantsim-container * {
    box-sizing: border-box;
}

.giantsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #0f3b34 0%, #155b4c 55%, #1f7d5c 100%);
    color: #fbf5e8;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(15, 59, 52, 0.32);
    border-bottom: 4px solid #c8922b;
}

.giantsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.giantsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f3d79a;
    background: rgba(200, 146, 43, 0.18);
    padding: 5px 14px;
    border-radius: 999px;
}

.giantsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #ece2cf;
}

.giantsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #155b4c;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.giantsim-period-counter #currentDay,
.giantsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #0f3b34;
}

.giantsim-round-name {
    background: #d9ecdf;
    color: #0f3b34;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.giantsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a3b18;
    background: #f7e2d4;
    padding: 4px 12px;
    border-radius: 999px;
}

.giantsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.giantsim-status-card {
    background: #fffdf8;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e6d9bf;
    box-shadow: 0 4px 14px rgba(15, 59, 52, 0.07);
    border-top: 4px solid #1f7d5c;
}

.giantsim-card-share { border-top-color: #1f7d5c; }
.giantsim-card-moat { border-top-color: #c8922b; }
.giantsim-card-ebitda { border-top-color: #2f6fb0; }
.giantsim-card-capital { border-top-color: #9a3b18; }

.giantsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8a795c;
}

.giantsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #0f3b34;
}

.giantsim-card-share .giantsim-value { color: #1f7d5c; }
.giantsim-card-moat .giantsim-value { color: #b9821f; }
.giantsim-card-ebitda .giantsim-value { color: #2f6fb0; }
.giantsim-card-capital .giantsim-value {
    color: #9a3b18;
    font-size: 1.5rem;
}

.giantsim-sublabel {
    font-size: 0.76rem;
    color: #8a795c;
    line-height: 1.35;
}

.giantsim-share-strong .giantsim-value { color: #1f7d5c; }
.giantsim-share-bleeding .giantsim-value { color: #c0392b; }

.giantsim-ebitda-collapse .giantsim-value { color: #c0392b; }

.giantsim-capital-over { border-top-color: #c0392b; }
.giantsim-capital-over .giantsim-value { color: #c0392b; }

.giantsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #0f3b34;
    color: #f3e8d2;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.giantsim-budget-bar #budgetDisplay {
    font-size: 1.0rem;
    letter-spacing: 0.2px;
    color: #f3d79a;
}

.giantsim-briefing {
    display: flex;
    gap: 14px;
    background: #fffdf8;
    border-left: 5px solid #c8922b;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(15, 59, 52, 0.06);
}

.giantsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.giantsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #0f3b34;
    margin-bottom: 6px;
}

.giantsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #463a28;
}

.giantsim-briefing-text strong { color: #1f7d5c; }
.giantsim-briefing-text em { color: #9a3b18; font-style: italic; }

.giantsim-controls {
    background: #fffdf8;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e6d9bf;
    box-shadow: 0 4px 14px rgba(15, 59, 52, 0.07);
}

.giantsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #0f3b34;
    border-bottom: 2px solid #efe3cf;
    padding-bottom: 8px;
}

.giantsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2c4a40;
    margin: 14px 0 6px;
}

.giantsim-container select,
.giantsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d8c7a4;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fdfaf2;
    color: #2a2118;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.giantsim-container select:focus,
.giantsim-container input[type="number"]:focus {
    outline: none;
    border-color: #1f7d5c;
    box-shadow: 0 0 0 3px rgba(31, 125, 92, 0.16);
}

.giantsim-container select option {
    background-color: #fffdf8;
    color: #2a2118;
}

.giantsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #c8922b;
}

.giantsim-range-readout,
.giantsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #155b4c;
    margin-top: 4px;
}

.giantsim-range-readout span:last-child,
.giantsim-alloc-readout span:nth-child(2) {
    color: #b9821f;
    font-weight: 800;
}

.giantsim-hint {
    font-size: 0.8rem;
    color: #8a795c;
    margin-top: 4px;
    line-height: 1.4;
}

.giantsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.giantsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f7f0e0;
    border: 1px solid #e6d9bf;
    border-radius: 9px;
    padding: 8px 12px;
}

.giantsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #2c4a40;
}

.giantsim-alloc-row input[type="number"] {
    width: 96px;
    flex: 0 0 96px;
}

.giantsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.giantsim-container .btn-primary {
    background: linear-gradient(135deg, #155b4c 0%, #1f7d5c 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    color: #fbf5e8;
    box-shadow: 0 6px 16px rgba(21, 91, 76, 0.30);
}

.giantsim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.giantsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #d8c7a4;
    color: #8a795c;
}

.giantsim-coach {
    background: #0f3b34;
    color: #eef6ef;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(15, 59, 52, 0.24);
    border-left: 5px solid #c8922b;
}

.giantsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #8fd3b9;
    margin-bottom: 8px;
}

.giantsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.giantsim-coach-body strong { color: #f3d79a; }
.giantsim-coach-body em { color: #f0b48f; font-style: italic; }

.giantsim-history,
.giantsim-chart {
    background: #fffdf8;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e6d9bf;
    box-shadow: 0 4px 14px rgba(15, 59, 52, 0.07);
}

.giantsim-history h3,
.giantsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #0f3b34;
}

.giantsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2c4a40;
}

.giantsim-container table#usfHistoryTable th {
    background: #eef3ec;
    color: #0f3b34;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #dbe7dc;
}

.giantsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0ece0;
}

.giantsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf6ec;
}

.giantsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .giantsim-container {
        padding: 14px;
    }
    .giantsim-header h1 {
        font-size: 1.7rem;
    }
    .giantsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .giantsim-value {
        font-size: 2rem;
    }
    .giantsim-card-capital .giantsim-value {
        font-size: 1.3rem;
    }
    .giantsim-clock {
        margin-left: 0;
    }
    .giantsim-period-counter {
        font-size: 0.88rem;
    }
    .giantsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .giantsim-alloc-row {
        flex-wrap: wrap;
    }
    .giantsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .giantsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 completion modal (dark-on-light for the framework's white modal) ===== */
.giantsim-cm { text-align: center; color: #2a2519; padding: 8px 4px 4px; }
.giantsim-cm-title { font-size: 1.05rem; font-weight: 700; color: #6d5a2f; margin-bottom: 10px; }
.giantsim-cm-scorewrap { margin: 4px 0 6px; }
.giantsim-cm-score { font-size: 3rem; font-weight: 800; line-height: 1; color: #6d5a2f; }
.giantsim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #8a795c; }
.giantsim-cm-scorelabel { font-size: .78rem; text-transform: uppercase; letter-spacing: .05em; color: #8a795c; }
.giantsim-cm-grade { font-size: 1.3rem; font-weight: 700; color: #2a2519; margin: 6px 0; }
.giantsim-cm-badges { margin: 8px 0 12px; }
.giantsim-cm-badge { display: inline-block; padding: 5px 12px; border-radius: 999px; font-size: .82rem; font-weight: 700; }
.giantsim-cm-badge-ok { background: #dfe9cf; color: #4a6b1e; border: 1px solid #6f9a34; }
.giantsim-cm-badge-fail { background: #f3d9d3; color: #8f2418; border: 1px solid #b8402f; }
.giantsim-cm-badge-warn { background: #f6ecd0; color: #856016; border: 1px solid #c99a34; }
.giantsim-cm-kpis { display: flex; gap: 10px; justify-content: center; flex-wrap: wrap; margin: 10px 0; }
.giantsim-cm-kpi { background: #f4f1e7; border: 1px solid #e6dfcc; border-radius: 10px; padding: 10px 14px; min-width: 92px; }
.giantsim-cm-kpi-n { font-size: 1.5rem; font-weight: 800; color: #6d5a2f; }
.giantsim-cm-kpi-l { font-size: .72rem; text-transform: uppercase; letter-spacing: .03em; color: #8a795c; }
.giantsim-cm-insights { text-align: left; margin: 12px auto 2px; max-width: 560px; background: #faf7ef; border: 1px solid #ece3d0; border-radius: 10px; padding: 10px 14px; }
.giantsim-cm-insights-h { font-weight: 700; color: #6d5a2f; margin-bottom: 6px; font-size: .9rem; }
.giantsim-cm-insights ul { margin: 0; padding-left: 18px; }
.giantsim-cm-insights li { color: #3b342a; font-size: .88rem; margin-bottom: 4px; }

