(function() {
    'use strict';

    class GiantsAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Competing with Giants`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Rp in miliar where money; % where margin/share).
            this.START_SHARE = 34;       // 34% national laundry volume share, #1
            this.START_MOAT = 55;        // warung + local-fit defensibility (0-100)
            this.START_MOAT_CEILING = 85;// best a healthy moat can reach (rebuilt trust has limits)
            this.START_EBITDA = 13.0;    // 13% EBITDA margin
            this.PRICEWAR_EBITDA = 6.0;  // price-match collapses margin toward 6%
            this.SHARE_DEFEND = 30;      // a strong, defended outcome (lose <4 points)
            this.CAPITAL_CAP = 350;      // Rp350 miliar deployable, 18 months, no top-up
            this.GIANT_GOAL = 15;        // Continental's 18-month national share goal

            // Permanent moat-ceiling penalties (the warung network/reps don't fully come back).
            this.WARUNG_STARVE_CEILING = 58; // starving warung distribution caps the moat forever
            this.TALENT_RAID_CEILING = 72;   // letting the giant poach the reps caps the moat forever
            this.MOAT_EROSION = 4;           // the giant keeps attacking every round
            this.GIANT_DRIFT = -4.0;         // steady share pull toward the analysts' feared loss
            this.SHARE_POS_SCALE = 0.55;     // your gains are hard-won; the drift stays competitive

            // Concept truths (the local-firm survival framework).
            this.TRUE_PRESSURE = `moderntrade`;
            this.TRUE_TRANSFER = `warung`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    share: this.START_SHARE,
                    moat: this.START_MOAT,
                    moatCeiling: this.START_MOAT_CEILING,
                    ebitda: this.START_EBITDA,
                    capitalUsed: 0,
                    armedRival: false,
                    pricedOut: false,
                    shareHistory: [this.START_SHARE],
                    moatHistory: [this.START_MOAT],
                    ebitdaHistory: [Math.round(this.START_EBITDA * 10)],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Defaults are a plausible-but-imperfect starting point (a hedged, spread-thin plan):
                // a click-through player lands in the middling "Local Champion Holds" band, not at the
                // top. Reaching "Unbeatable on Home Turf" requires the deliberate concept-correct moves.
                state.decisions = {
                    pressure: `moderntrade`,
                    transfer: `warung`,
                    honesty: 50,
                    posture: `defenddodge`,
                    pricing: `partial`,
                    weapon: `warung`,
                    warung: 90,
                    rnd: 70,
                    modern: 120,
                    talent: 70,
                    partner: `firewall`,
                    expansion: `defensive`,
                    institutionalize: `heroics`,
                    board: `survival`,
                    conviction: 55
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const pres = document.getElementById(`pressureInput`);
                const trans = document.getElementById(`transferInput`);
                const hon = document.getElementById(`honestyInput`);
                if (pres) decisions.pressure = pres.value;
                if (trans) decisions.transfer = trans.value;
                if (hon) decisions.honesty = parseInt(hon.value, 10);
                if (!Number.isFinite(decisions.honesty) || decisions.honesty < 0 || decisions.honesty > 100) {
                    warn(`warn_honesty_range`); return false;
                }
            } else if (round === 2) {
                const post = document.getElementById(`postureInput`);
                const price = document.getElementById(`pricingInput`);
                const weap = document.getElementById(`weaponInput`);
                if (post) decisions.posture = post.value;
                if (price) decisions.pricing = price.value;
                if (weap) decisions.weapon = weap.value;
            } else if (round === 3) {
                const w = document.getElementById(`warungInput`);
                const r = document.getElementById(`rndInput`);
                const m = document.getElementById(`modernInput`);
                const tl = document.getElementById(`talentInput`);
                const p = document.getElementById(`partnerInput`);
                if (w) decisions.warung = parseFloat(w.value);
                if (r) decisions.rnd = parseFloat(r.value);
                if (m) decisions.modern = parseFloat(m.value);
                if (tl) decisions.talent = parseFloat(tl.value);
                if (p) decisions.partner = p.value;
                const parts = [decisions.warung, decisions.rnd, decisions.modern, decisions.talent];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round(decisions.warung + decisions.rnd + decisions.modern + decisions.talent);
                if (total !== this.CAPITAL_CAP) {
                    warn(`warn_alloc_total`); return false;
                }
            } else if (round === 4) {
                const ex = document.getElementById(`expansionInput`);
                const inst = document.getElementById(`institutionalizeInput`);
                const bo = document.getElementById(`boardInput`);
                const cv = document.getElementById(`convictionInput`);
                if (ex) decisions.expansion = ex.value;
                if (inst) decisions.institutionalize = inst.value;
                if (bo) decisions.board = bo.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // shareDelta: change in national laundry share points (the headline).
            // moatDelta: defensibility of the warung/local-fit advantage.
            // ebitdaDelta: margin movement (price war is the big destroyer).
            let shareDelta = 0, moatDelta = 0, ebitdaDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Map the battlefield: globalised pressure + transferable assets (Frost two-axis).
                if (d.pressure === this.TRUE_PRESSURE) {
                    moatDelta += 5; shareDelta += 1; coachKey = `coach_r1_pressure_right`;
                } else if (d.pressure === `everywhere`) {
                    moatDelta -= 6; shareDelta -= 2; coachKey = `coach_r1_everywhere`;
                } else if (d.pressure === `warung`) {
                    moatDelta -= 8; shareDelta -= 2; coachKey = `coach_r1_warung`;
                } else {
                    moatDelta -= 11; shareDelta -= 4; coachKey = `coach_r1_none`;
                }

                // Transferability is the pivotal diagnostic: the warungs are non-transferable.
                if (d.transfer === this.TRUE_TRANSFER) {
                    moatDelta += 7; shareDelta += 1;
                    if (d.pressure === this.TRUE_PRESSURE) coachKey = `coach_r1_map_sharp`;
                } else if (d.transfer === `brand`) {
                    moatDelta -= 9; shareDelta -= 2; coachKey = `coach_r1_brand`;
                } else if (d.transfer === `balance`) {
                    moatDelta -= 7; ebitdaDelta -= 0.4; coachKey = `coach_r1_balance`;
                } else {
                    moatDelta -= 5; coachKey = `coach_r1_rnd`;
                }

                // Honesty: willingness to concede ground the giant will win (refuse some battles).
                if (d.honesty >= 60) { moatDelta += 3; }
                else if (d.honesty <= 25) { moatDelta -= 7; shareDelta -= 2; coachKey = `coach_r1_lowhonesty`; }

                summaryKey = (d.pressure === this.TRUE_PRESSURE && d.transfer === this.TRUE_TRANSFER) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Posture: defend the warung-strong core + dodge the premium tier (concept-correct).
                switch (d.posture) {
                    case `defenddodge`: moatDelta += 6; shareDelta += 2; coachKey = `coach_r2_defenddodge`; break;
                    case `defendall`: moatDelta -= 7; shareDelta -= 3; ebitdaDelta -= 0.8; coachKey = `coach_r2_defendall`; break;
                    case `globalcontend`: moatDelta -= 9; shareDelta -= 4; ebitdaDelta -= 1.2; coachKey = `coach_r2_globalcontend`; break;
                    case `retreat`: moatDelta -= 14; shareDelta -= 6; coachKey = `coach_r2_retreat`; break;
                }

                // Pricing: holding price and competing on local value beats the price-war trap.
                switch (d.pricing) {
                    case `value`: shareDelta += 2; moatDelta += 2; coachKey = (d.posture === `defenddodge`) ? `coach_r2_value` : coachKey; break;
                    case `partial`: shareDelta -= 1; ebitdaDelta -= 0.8; break;
                    case `match`:
                        // The price war: matching collapses EBITDA toward 6% and plays to the giant's scale.
                        shareDelta += 2; ebitdaDelta -= 4.5; ds.pricedOut = true; coachKey = `coach_r2_match`; break;
                }

                // Weapon: warung + local R&D is the non-transferable advantage; TV/modern-trade is the giant's game.
                switch (d.weapon) {
                    case `warung`: moatDelta += 7; shareDelta += 1; break;
                    case `tvmodern`: moatDelta -= 9; shareDelta -= 2; coachKey = `coach_r2_tvmodern`; break;
                    case `discount`: ebitdaDelta -= 2.0; moatDelta -= 3; coachKey = `coach_r2_discount`; break;
                }

                summaryKey = (d.posture === `defenddodge` && d.pricing !== `match` && d.weapon === `warung`) ? `sum_r2_good`
                    : (d.pricing === `match` ? `sum_r2_pricewar` : `sum_r2_weak`);
            } else if (round === 3) {
                // Allocate the scarce Rp350 miliar + the partnership dilemma.
                spend = d.warung + d.rnd + d.modern + d.talent; // bounded to 350 by validation
                const warungShare = d.warung / this.CAPITAL_CAP;
                const talentShare = d.talent / this.CAPITAL_CAP;
                const modernShare = d.modern / this.CAPITAL_CAP;
                const rndShare = d.rnd / this.CAPITAL_CAP;

                // Funding the non-transferable moat (warungs) is the highest-leverage spend.
                // Centred so a strong warung allocation (~0.45+) is clearly positive and starving it
                // (<0.25) is clearly negative — but never large enough to peg the meter alone.
                moatDelta += Math.round(warungShare * 30 - 10);
                shareDelta += (warungShare * 4 - 1);

                // Starving the warung network is PERMANENT: rep coverage lapses, informal-credit
                // relationships break and the last-mile trust cannot simply be rebought next round.
                // It caps the moat for the rest of the game (Frost — the moat is embodied, not bought).
                if (warungShare < 0.25) {
                    ds.moatCeiling = Math.min(ds.moatCeiling, this.WARUNG_STARVE_CEILING);
                    coachKey = `coach_r3_abandonmoat`;
                }

                // Local R&D deepens advantages the giant cannot easily localise.
                moatDelta += Math.round(rndShare * 8);

                // A modern-trade beachhead helps a little but is the giant's turf — diminishing, never decisive.
                shareDelta += (modernShare * 2);
                if (modernShare > 0.45) { moatDelta -= 5; ebitdaDelta -= 0.6; } // over-investing the giant's battlefield

                // Talent retention: the moat is embodied in people the giant raids at +40%. Letting the
                // best regional managers walk (with their warung relationships) is also a permanent loss.
                if (talentShare >= 0.15) { moatDelta += 4; shareDelta += 1; }
                else {
                    moatDelta -= 9; shareDelta -= 3; coachKey = `coach_r3_talent`;
                    ds.moatCeiling = Math.min(ds.moatCeiling, this.TALENT_RAID_CEILING);
                }

                // Coaching for the dominant allocation pattern.
                if (warungShare < 0.25 && modernShare > 0.30) coachKey = `coach_r3_abandonmoat`;
                else if (warungShare >= 0.40 && talentShare >= 0.15) coachKey = `coach_r3_concentrate`;
                else if (coachKey === `coach_default`) coachKey = `coach_r3_spread`;

                // The partner-vs-arm-the-rival dilemma. Taking the open deal arms the rival INSIDE the
                // one non-transferable moat — a permanent ceiling drop the late rounds cannot heal away.
                switch (d.partner) {
                    case `decline`: moatDelta += 5; coachKey = (warungShare >= 0.40) ? `coach_r3_decline` : coachKey; break;
                    case `firewall`: moatDelta += 1; ebitdaDelta += 0.5; coachKey = `coach_r3_firewall`; break;
                    case `open`:
                        moatDelta -= 18; shareDelta -= 3; ebitdaDelta += 1.0; ds.armedRival = true;
                        ds.moatCeiling = Math.min(ds.moatCeiling, 45); // moat can never fully recover once breached
                        coachKey = `coach_r3_open`; break;
                }

                summaryKey = (warungShare >= 0.40 && talentShare >= 0.15 && d.partner !== `open`) ? `sum_r3_good`
                    : (d.partner === `open` ? `sum_r3_armed` : `sum_r3_weak`);
            } else if (round === 4) {
                // 18-month outcome + survival strategy.
                switch (d.expansion) {
                    case `adjacent`: shareDelta += 2; moatDelta += 5; coachKey = `coach_r4_adjacent`; break;
                    case `headon`: shareDelta -= 4; ebitdaDelta -= 1.5; moatDelta -= 5; coachKey = `coach_r4_headon`; break;
                    case `defensive`: shareDelta -= 1; moatDelta -= 3; coachKey = `coach_r4_defensive`; break;
                }

                // Institutionalising the local advantage so the next giant is met from strength.
                switch (d.institutionalize) {
                    case `embed`: moatDelta += 7; shareDelta += 1; break;
                    case `heroics`: moatDelta -= 7; coachKey = `coach_r4_heroics`; break;
                    case `nothing`: moatDelta -= 13; shareDelta -= 2; coachKey = `coach_r4_nothing`; break;
                }

                // The board pitch.
                switch (d.board) {
                    case `survival`: shareDelta += 2; moatDelta += 3; coachKey = (d.institutionalize === `embed`) ? `coach_r4_survival` : coachKey; break;
                    case `pricewin`: ebitdaDelta -= 2.0; moatDelta -= 5; coachKey = `coach_r4_pricewin`; break;
                    case `exit`: shareDelta -= 6; moatDelta -= 16; coachKey = `coach_r4_exit`; break;
                }

                // Conviction nudges share defence.
                shareDelta += Math.round((d.conviction - 60) / 15);

                summaryKey = (d.expansion === `adjacent` && d.institutionalize === `embed` && d.board === `survival`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting (capital pool committed in R3).
            ds.capitalUsed = Math.min(this.CAPITAL_CAP, Math.round(ds.capitalUsed + spend));

            // The giant keeps attacking: the warung moat erodes a little every round unless re-invested
            // (Frost — MNEs increasingly localise innovation), so a wasted round costs you permanently
            // and no single round can simply re-peg the meter to its ceiling.
            const MOAT_EROSION = this.MOAT_EROSION;
            ds.moat = Math.max(0, Math.min(ds.moatCeiling, ds.moat + moatDelta - MOAT_EROSION));

            // Share is an incumbent's defence, not a growth meter, and it never grows above the starting
            // 34%. Continental applies a steady baseline pull every round; a STRONG moat resists most of
            // it (the whole point of the framework), a thin moat lets the share bleed through toward the
            // analysts' feared 8-12 point loss. Your own share GAINS are hard-won and scaled down so the
            // giant's pull stays a live force — only genuinely strong play actually holds the line at 34,
            // and any real mistake (price war scarring the moat, abandoning the warungs, a wrong posture)
            // visibly bleeds share. This keeps the share KPI a real, moving lever rather than a pegged
            // meter sitting at its cap regardless of decisions.
            const giantDrift = this.GIANT_DRIFT;
            const positivePull = Math.max(0, shareDelta) * this.SHARE_POS_SCALE;
            const negativePull = Math.min(0, shareDelta);
            const ownShare = positivePull + negativePull;
            const moatResistance = Math.max(0, Math.min(0.82, ds.moat / 108)); // 0..0.82 — even a strong moat bleeds a little
            const netShare = ownShare + giantDrift * (1 - moatResistance);
            ds.share = Math.max(15, Math.min(this.START_SHARE, ds.share + netShare)); // cannot grow above the starting 34%

            // EBITDA never rises above the starting 13% margin; a price war keeps it low and it heals
            // only mildly when no war is running. This makes the price war the dominant margin destroyer.
            ds.ebitda = ds.ebitda + ebitdaDelta;
            if (!ds.pricedOut && ebitdaDelta >= 0 && ds.ebitda < this.START_EBITDA) {
                ds.ebitda = Math.min(this.START_EBITDA, ds.ebitda + 0.4); // mild healing when not at war
            }
            ds.ebitda = Math.max(2.0, Math.min(this.START_EBITDA, ds.ebitda));

            ds.shareHistory.push(Math.round(ds.share * 10) / 10);
            ds.moatHistory.push(Math.round(ds.moat));
            ds.ebitdaHistory.push(Math.round(ds.ebitda * 10));

            // v1.1.0 FIX - persist the composite where the grading/reporting layer reads it
            // (express_resolveDomainScore -> domainState.performance.overallScore), every period.
            const overallScore = this._composite(ds);
            ds.performance = { overallScore: overallScore };

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                share: Math.round(ds.share * 10) / 10,
                shareDelta: Math.round(netShare * 10) / 10,
                moat: Math.round(ds.moat),
                moatDelta: Math.round(moatDelta - MOAT_EROSION),
                ebitda: Math.round(ds.ebitda * 10) / 10,
                ebitdaDelta: Math.round(ebitdaDelta * 10) / 10,
                capitalUsed: ds.capitalUsed,
                armedRival: ds.armedRival,
                pricedOut: ds.pricedOut,
                score: overallScore,
                overallScore: overallScore,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);
            uiManager.bind(`shareDisplay`, `domainState.share`, (v) => {
                const card = document.querySelector(`.giantsim-card-share`);
                if (card) {
                    card.classList.toggle(`giantsim-share-strong`, Number(v) >= this.SHARE_DEFEND);
                    card.classList.toggle(`giantsim-share-bleeding`, Number(v) < 26);
                }
                return (Math.round(Number(v) * 10) / 10) + `%`;
            });
            uiManager.bind(`moatDisplay`, `domainState.moat`, (v) => Math.round(v));
            uiManager.bind(`ebitdaDisplay`, `domainState.ebitda`, (v) => {
                const card = document.querySelector(`.giantsim-card-ebitda`);
                if (card) card.classList.toggle(`giantsim-ebitda-collapse`, Number(v) < 9);
                return (Math.round(Number(v) * 10) / 10).toFixed(1) + `%`;
            });
            uiManager.bind(`capitalDisplay`, `domainState.capitalUsed`, (v) => {
                const card = document.querySelector(`.giantsim-card-capital`);
                if (card) card.classList.toggle(`giantsim-capital-over`, Number(v) > this.CAPITAL_CAP + 0.001);
                return `Rp` + Math.round(Number(v)) + ` / Rp350 mrd`;
            });

            const self = this;

            // Honesty slider readout.
            const hon = document.getElementById(`honestyInput`);
            const honReadout = document.getElementById(`honestyReadout`);
            if (hon && honReadout) {
                honReadout.textContent = hon.value;
                hon.addEventListener(`input`, function() { honReadout.textContent = hon.value; });
            }

            // Capital allocation live total (must total 350).
            const allocIds = [`warungInput`, `rndInput`, `modernInput`, `talentInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total);
                if (allocReadout) allocReadout.textContent = total;
                const bar = document.querySelector(`.giantsim-alloc-readout`);
                if (bar) bar.style.color = (total !== self.CAPITAL_CAP) ? `#c0392b` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

        // v1.1.0 - trajectory composite 0-100 the reporting layer reads. Formula identical to
        // getPerformanceSummary (worst share ever + average moat sustained + end-margin).
        // Reads the histories, so call it AFTER the round's history push. Clamped defensively.
        _composite(ds) {
            const ebitda = Math.round(ds.ebitda * 10) / 10;
            const post = ds.shareHistory.slice(1);
            const minShare = post.length ? Math.min.apply(null, post) : (Math.round(ds.share * 10) / 10);
            const moatAvg = ds.moatHistory.length ? ds.moatHistory.reduce((a, b) => a + b, 0) / ds.moatHistory.length : Math.round(ds.moat);
            return Math.max(0, Math.min(100, Math.round(
                Math.min(100, (minShare / this.START_SHARE) * 100) * 0.40 +
                Math.min(100, moatAvg) * 0.35 +
                Math.min(100, (ebitda / this.START_EBITDA) * 100) * 0.25
            )));
        }

        // v1.1.0 - safe i18n lookup with English fallback (chart/legend chrome).
        _cl(key, fallback) {
            try {
                const s = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(key) : key;
                return (s && s !== key) ? s : fallback;
            } catch (e) { return fallback; }
        }

        getChartConfig() {
            return {
                giantsChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: this._cl(`legend_share`, `National Share %`),
                                data: [],
                                borderColor: `#1f7d5c`,
                                backgroundColor: `rgba(31,125,92,0.14)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#1f7d5c`,
                                yAxisID: `y`
                            },
                            {
                                label: this._cl(`legend_moat`, `Moat Strength`),
                                data: [],
                                borderColor: `#c8922b`,
                                backgroundColor: `rgba(200,146,43,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#c8922b`,
                                yAxisID: `y`
                            },
                            {
                                label: this._cl(`legend_ebitda`, `EBITDA Margin % (×1)`),
                                data: [],
                                borderColor: `#2f6fb0`,
                                backgroundColor: `rgba(47,111,176,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#2f6fb0`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#2a2118`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#8a795c` }, grid: { color: `rgba(15,59,52,0.08)` },
                                title: { display: true, text: this._cl(`axis_scale`, `Share % · Moat 0–100 · EBITDA %`), color: `#8a795c` }
                            },
                            x: {
                                ticks: { color: `#8a795c` }, grid: { color: `rgba(15,59,52,0.06)` },
                                title: { display: true, text: this._cl(`axis_round`, `Round`), color: `#8a795c` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.shareHistory.map((_, i) => (i === 0 ? `Start` : `R` + i));
            return {
                giantsChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.shareHistory },
                        { data: ds.moatHistory },
                        { data: ds.ebitdaHistory.map((v) => v / 10) }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const share = Math.round(ds.share * 10) / 10;
            const moat = Math.round(ds.moat);
            const ebitda = Math.round(ds.ebitda * 10) / 10;

            const defended = share >= this.SHARE_DEFEND;          // lost fewer than ~4 points
            const moatHeld = moat >= 60;
            const marginIntact = ebitda >= 11.0;                  // FMCG mass norm 11-15%

            // Trajectory-aware scoring: the composite rewards holding the line EVERY round, not just
            // recovering by the finale. Use the worst share the giant ever forced and the average moat
            // sustained across the campaign, so a clean defence strictly out-scores a wobbly one that
            // happened to end well. Margin uses the end-state (the price war's scar is permanent).
            const post = ds.shareHistory.slice(1);               // drop the "Start" seed
            const minShare = post.length ? Math.min.apply(null, post) : share;
            const moatAvg = ds.moatHistory.length ? ds.moatHistory.reduce((a, b) => a + b, 0) / ds.moatHistory.length : moat;
            const composite = this._composite(ds);

            let gradeKey = `grade_alsoran`;
            if (defended && moatHeld && marginIntact && composite >= 88) gradeKey = `grade_unbeatable`;
            else if (defended && moatHeld && marginIntact) gradeKey = `grade_champion`;
            else if (ds.armedRival && moat < 45) gradeKey = `grade_armed`;
            else if (ds.pricedOut && ebitda < 9) gradeKey = `grade_bledout`;
            else if (defended) gradeKey = `grade_survived`;
            else if (share >= 26) gradeKey = `grade_wounded`;
            const performance = window.mySimulation.t(gradeKey);

            const insights = [];
            if (defended && moatHeld && marginIntact) insights.push(window.mySimulation.t(`insight_champion`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (ds.pricedOut && ebitda < 9) insights.push(window.mySimulation.t(`insight_pricewar`));
            if (ds.armedRival) insights.push(window.mySimulation.t(`insight_armed`));
            if (moat < 45) insights.push(window.mySimulation.t(`insight_moatlost`));
            if (share <= 26) insights.push(window.mySimulation.t(`insight_sharelost`));
            if (defended && moatHeld && marginIntact && composite >= 88) insights.push(window.mySimulation.t(`insight_compound`));

            return {
                share: share,
                moat: moat,
                ebitda: ebitda,
                defended: defended,
                composite: composite,
                performance: performance,
                gradeKey: gradeKey,
                passed: (defended && moatHeld && marginIntact),
                armed: !!ds.armedRival,
                priced: !!ds.pricedOut,
                insights: insights
            };
        }

        // v1.1.0 FIX - real completion modal (score / localized grade / MET or distinct-failure
        // badge / KPI strip / insights). Replaces the framework's generic fallback.
        formatCompletionMessage(summary) {
            const t = (k) => (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(k) : k;
            const s = summary || {};
            const score = Number.isFinite(s.composite) ? s.composite : 0;
            const grade = s.performance || t(s.gradeKey || `grade_alsoran`);
            const passed = !!s.passed;
            const share = (s.share != null) ? s.share : 0;
            const moat = Math.round(s.moat != null ? s.moat : 0);
            const ebitda = (s.ebitda != null) ? Number(s.ebitda).toFixed(1) : `0.0`;
            let badge;
            if (passed) {
                badge = `<span class="giantsim-cm-badge giantsim-cm-badge-ok">\u2713 ` + t(`cm_met`) + `</span>`;
            } else if (s.armed && (s.moat < 45)) {
                badge = `<span class="giantsim-cm-badge giantsim-cm-badge-fail">\u2715 ` + t(`cm_fail_armed`) + `</span>`;
            } else if (s.priced && (s.ebitda < 9)) {
                badge = `<span class="giantsim-cm-badge giantsim-cm-badge-fail">\u2715 ` + t(`cm_fail_priced`) + `</span>`;
            } else {
                badge = `<span class="giantsim-cm-badge giantsim-cm-badge-warn">\u2022 ` + t(`cm_missed`) + `</span>`;
            }
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const insightHtml = insights.length
                ? `<div class="giantsim-cm-insights"><div class="giantsim-cm-insights-h">` + t(`cm_insights`) + `</div><ul>` + insights.map((x) => `<li>` + x + `</li>`).join(``) + `</ul></div>`
                : ``;
            return `
                <div class="giantsim-cm">
                    <div class="giantsim-cm-title">` + t(`cm_title`) + `</div>
                    <div class="giantsim-cm-scorewrap">
                        <div class="giantsim-cm-score">` + score + `<span class="giantsim-cm-score-max">/100</span></div>
                        <div class="giantsim-cm-scorelabel">` + t(`cm_score_of`) + `</div>
                    </div>
                    <div class="giantsim-cm-grade">` + grade + `</div>
                    <div class="giantsim-cm-badges">` + badge + `</div>
                    <div class="giantsim-cm-kpis">
                        <div class="giantsim-cm-kpi"><div class="giantsim-cm-kpi-n">` + share + `%</div><div class="giantsim-cm-kpi-l">` + t(`cm_share`) + `</div></div>
                        <div class="giantsim-cm-kpi"><div class="giantsim-cm-kpi-n">` + moat + `</div><div class="giantsim-cm-kpi-l">` + t(`cm_moat`) + `</div></div>
                        <div class="giantsim-cm-kpi"><div class="giantsim-cm-kpi-n">` + ebitda + `%</div><div class="giantsim-cm-kpi-l">` + t(`cm_ebitda`) + `</div></div>
                    </div>
                    ` + insightHtml + `
                </div>
            `;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.armedRival && ds.moat < 50) return window.mySimulation.t(`hint_armed`);
            if (ds.pricedOut && ds.ebitda < 9) return window.mySimulation.t(`hint_pricewar`);
            if (ds.moat < 40) return window.mySimulation.t(`hint_moat`);
            if (state.currentPeriod >= 3 && ds.share < 27) return window.mySimulation.t(`hint_behind`);
            if (ds.share >= this.SHARE_DEFEND && ds.moat >= 65 && ds.ebitda >= 11) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.share`, label: `Share`, i18nKey: `col_share`, formatter: (v) => (Math.round(v * 10) / 10) + `%` },
                { key: `results.moat`, label: `Moat`, i18nKey: `col_moat`, formatter: (v) => Math.round(v) },
                { key: `results.ebitda`, label: `EBITDA`, i18nKey: `col_ebitda`, formatter: (v) => (Math.round(v * 10) / 10).toFixed(1) + `%` }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

        getTranslations() {
            return {
                en: {
                    title:                  `Competing with Giants`,
                    grade_alsoran:          `Declining Also-Ran`,
                    grade_unbeatable:       `Unbeatable on Home Turf`,
                    grade_champion:         `Local Champion Holds`,
